WITH eligible AS (SELECT s.* FROM departments s WHERE EXISTS (SELECT 1 FROM employees ch WHERE ch.dept_id = s.id AND ch.hire_date <= '2025-05-01')) SELECT dept_name, CASE WHEN budget >= 3496000 THEN 'PREMIUM' ELSE 'STANDARD' END AS budget_tier, SUM(budget) AS total_budget, COUNT(*) AS event_count, GROUPING_ID() AS grouping_level FROM eligible GROUP BY GROUPING SETS ((dept_name, CASE WHEN budget >= 3496000 THEN 'PREMIUM' ELSE 'STANDARD' END), (dept_name), ());
